//! Original five lanes for the explicit same-actor phase mode.
//! Every accepted channel keeps the startup Instant; the common stop gate
//! separately retains the original BOOTTIME limit and wakes blocked streams.

use super::*;
use crate::same_actor_q24_phase_gate::CloseSameActorPhaseOnDrop;
use crate::same_actor_q24_phase_gate::SameActorPhaseGate;
use std::sync::Arc;

impl HostAuthorityService {
    pub(crate) fn serve_original_phase_lane_until(
        &self,
        lane: HostAuthorityLane,
        stream: UnixStream,
        mut policy: HostAuthorityPeerPolicy,
        owner_pidfd: OwnedFd,
        gate: &Arc<SameActorPhaseGate>,
    ) -> Result<(), HostIssuerTransportError> {
        let _closing = CloseSameActorPhaseOnDrop::new(gate);
        gate.require_open().map_err(unavailable)?;
        let _stream_stop = gate.retain_original_stream(&stream).map_err(unavailable)?;
        let bound = match lane {
            HostAuthorityLane::Observation => 16 * 1024,
            HostAuthorityLane::Issuer => 64 * 1024,
            HostAuthorityLane::Checkpoint => 32 * 1024,
            HostAuthorityLane::DeviceConsumerFrontier
            | HostAuthorityLane::NotesConsumerFrontier => 16 * 1024,
        };
        policy.request_bound = bound;
        policy.response_bound = bound;
        if matches!(lane, HostAuthorityLane::Checkpoint)
            && let Some(checkpoint) = &self.checkpoint
        {
            checkpoint.validate_peer(policy.peer).map_err(unavailable)?;
        }
        let mut channel = HostAuthorityPeerChannel::from_stream_until(
            stream, policy, owner_pidfd, gate.deadline().instant(),
        )?;
        while channel.exchange(|bytes| {
            let _admission = gate.enter_original_lane().map_err(unavailable)?;
            let response = self.handle(lane, bytes)?;
            gate.require_open().map_err(unavailable)?;
            Ok(response)
        })? {
            // The framed ACK has completed. Instant-only transport checks
            // do not replace the phase's retained BOOTTIME boundary.
            gate.require_open().map_err(unavailable)?;
        }
        // These five owner lanes are required for the entire phase.
        // EOF is not a completion receipt and closes every participating lane.
        Err(HostIssuerTransportError::Closed)
    }
}

//! Explicit same-session, same-actor phase mode. Existing default startup
//! constructors and serving paths retain their behavior.
//!
//! This mode never authorizes a different agent, cell, principal, process or
//! spawn. It does not implement an independent consumer or cold recovery.

use super::*;
use std::sync::Arc;

use codex_hepta_contracts::RootAuthorityDirectory;
use crate::same_actor_q24_phase_gate::CloseSameActorPhaseOnDrop;
use crate::same_actor_q24_phase_gate::SameActorPhaseDeadline;
use crate::same_actor_q24_phase_gate::SameActorPhaseGate;
use crate::same_actor_q24_phase_protocol::OriginalPhaseBootstrap;
use crate::same_actor_q24_phase_protocol::START_PURPOSE;
use crate::same_actor_q24_phase_protocol::CONTROL_SOCKET;
use crate::same_actor_q24_phase_record::OriginalPhaseRecord;
use crate::same_actor_q24_phase_record::PhaseIdentity;

#[path = "authority_host_same_actor_q24_scope_cap.rs"]
mod scope_cap;
pub use scope_cap::RootSameActorScopeEnrollmentCapabilityV1;
pub use scope_cap::RootSameActorScopedEnrollmentV1;

#[path = "authority_host_same_actor_q24_phase_worker.rs"]
mod worker;

pub struct RootSameActorPhaseStartV1 {
    pub initial_capability: generation_initial::RootSameActorInitialEnrollmentCapabilityV1,
    pub initial_offer: crate::RootGenerationInitialOfferV1,
    pub phase_offer: crate::root_production_handoff::same_actor_phase::RootSameActorPhaseOfferV1,
    pub scope_capability: RootSameActorScopeEnrollmentCapabilityV1,
}

/// The only phase constructor captures both Root-local absolute limits before
/// opening any original service or publishing A. Every phase worker receives
/// these same values. A later enable, owner arrival or ACK cannot restart them.
pub struct PreparedRootSameActorQ24PhaseV1 {
    original: PreparedHostAuthoritySession,
    gate: Arc<SameActorPhaseGate>,
    record: OriginalPhaseRecord,
    descriptor: OriginalPhaseBootstrap,
    model: crate::HostAuthorityQ24ModelFactoryReservationV1,
    scope: scope_cap::ScopeRuntime,
    start: Option<RootSameActorPhaseStartV1>,
    closing: CloseSameActorPhaseOnDrop,
}

impl PreparedRootSameActorQ24PhaseV1 {
    pub fn open(
        config_file: &Path,
        registration_file: &Path,
        owner_pidfd: OwnedFd,
        current_directory: Arc<RootAuthorityDirectory>,
        initial: crate::HostGenerationInitialDeploymentV1,
        model: crate::HostAuthorityQ24ModelFactoryReservationV1,
    ) -> io::Result<Self> {
        let config: HostAuthorityServiceConfig = read_root_json(config_file)?;
        let deadline = SameActorPhaseDeadline::at_original_service_start(
            std::time::Duration::from_millis(config.lifetime_ms),
        )?;
        let original = PreparedHostAuthoritySession::open(
            config_file, registration_file, owner_pidfd,
        )?;
        Self::capture_original_phase(original, config, deadline, current_directory, initial, model)
    }

    pub async fn prepare_fresh_from_registered(
        config_file: &Path,
        registration_file: &Path,
        owner_pidfd: OwnedFd,
        current_directory: Arc<RootAuthorityDirectory>,
        initial: crate::HostGenerationInitialDeploymentV1,
        model: crate::HostAuthorityQ24ModelFactoryReservationV1,
    ) -> io::Result<Self> {
        let config: HostAuthorityServiceConfig = read_root_json(config_file)?;
        let deadline = SameActorPhaseDeadline::at_original_service_start(
            std::time::Duration::from_millis(config.lifetime_ms),
        )?;
        let original = PreparedHostAuthoritySession::prepare_fresh_from_registered(
            config_file, registration_file, owner_pidfd,
        ).await?;
        Self::capture_original_phase(original, config, deadline, current_directory, initial, model)
    }

    fn capture_original_phase(
        mut original: PreparedHostAuthoritySession,
        config: HostAuthorityServiceConfig,
        deadline: SameActorPhaseDeadline,
        current_directory: Arc<RootAuthorityDirectory>,
        initial: crate::HostGenerationInitialDeploymentV1,
        model: crate::HostAuthorityQ24ModelFactoryReservationV1,
    ) -> io::Result<Self> {
        let gate = SameActorPhaseGate::from_original_deadline(deadline)?;
        let mut closing = CloseSameActorPhaseOnDrop::new(&gate);
        if serde_json::to_vec(&config).map_err(io::Error::other)?
            != serde_json::to_vec(&original.config).map_err(io::Error::other)?
            || original.learning.is_some()
            || original.publication.is_some()
            || original.initial_publication.is_some()
            || original.root_admin.is_some()
            || original.config.sockets.device_frontier.is_none()
            || original.config.sockets.notes_frontier.is_none()
        {
            return Err(io::Error::other("same-actor phase requires the unchanged original startup"));
        }
        gate.require_open()?;
        let (initial_capability, initial_offer) =
            original.enable_generation_initial(initial.clone())?;
        let mut retained = None;
        original.service.with_initial_publication_context(
            &original.config, &original.registration, &original.owner_pidfd, |proof| {
                gate.require_open()?;
                let phase_identity = PhaseIdentity {
                    root: codex_hepta_memory::CognitiveCheckpointPeerLifetime {
                        uid: 0,
                        pid: std::process::id(),
                        boot_id: original.registration.boot_id.clone(),
                        process_start_ticks: phase_root_start()?,
                    },
                    consumer: codex_hepta_memory::CognitiveCheckpointPeerLifetime {
                        uid: original.config.peer_uid,
                        pid: original.registration.peer_pid,
                        boot_id: original.registration.boot_id.clone(),
                        process_start_ticks: original.registration.process_start_ticks,
                    },
                    identity: crate::neuron_generation_process_identity_digest_v1(
                        &original.registration.registered_identity.identity()?,
                    ).map_err(io::Error::other)?.to_string(),
                    writer: proof,
                    initial: initial.clone(),
                    model_reservation: serde_json::to_string(&model).map_err(io::Error::other)?,
                    root_end_boottime_ns: deadline.boottime_ns(),
                };
                let record = OriginalPhaseRecord::reserve(
                    Arc::clone(&current_directory), phase_identity.clone(),
                )?;
                let descriptor = OriginalPhaseBootstrap {
                    purpose: START_PURPOSE.into(),
                    phase: record.binding()?,
                    original: phase_identity,
                    control_socket: original.config.sockets.observation.parent()
                        .ok_or_else(|| io::Error::other("original Root listener parent missing"))?
                        .join(CONTROL_SOCKET),
                };
                let encoded = serde_json::to_vec(&descriptor).map_err(io::Error::other)?;
                let sealed = crate::authority_host_bootstrap_seal::seal_bytes(&encoded)?;
                gate.require_open()?;
                retained = Some((record, descriptor, sealed));
                Ok(())
            },
        )?;
        gate.require_open()?;
        let (record, descriptor, sealed) = retained
            .ok_or_else(|| io::Error::other("original phase startup capture missing"))?;
        let (scope, scope_capability) =
            scope_cap::ScopeRuntime::mint(descriptor.original.root.clone(), &gate);
        let start = RootSameActorPhaseStartV1 {
            initial_capability: initial_capability.into_same_actor_phase(&gate, &current_directory),
            initial_offer,
            phase_offer: crate::root_production_handoff::same_actor_phase::RootSameActorPhaseOfferV1 {
                bootstrap: sealed,
                gate: Arc::clone(&gate),
                closing: CloseSameActorPhaseOnDrop::new(&gate),
            },
            scope_capability,
        };
        closing.disarm();
        let closing = CloseSameActorPhaseOnDrop::new(&gate);
        Ok(Self { original, gate, record, descriptor, model, scope, start: Some(start), closing })
    }

    pub fn take_start(&mut self) -> io::Result<RootSameActorPhaseStartV1> {
        let mut closing = CloseSameActorPhaseOnDrop::new(&self.gate);
        self.gate.require_open()?;
        let start = self.start.take()
            .ok_or_else(|| io::Error::other("original phase start was already consumed"))?;
        closing.disarm();
        Ok(start)
    }

    pub fn seal_bootstrap(&self, consumer_state_root: &Path) -> io::Result<File> {
        let mut closing = CloseSameActorPhaseOnDrop::new(&self.gate);
        let _admission = self.gate.enter_original_lane()?;
        let bootstrap = self.original.seal_bootstrap(consumer_state_root)?;
        self.gate.require_open()?;
        closing.disarm();
        Ok(bootstrap)
    }

    pub fn handoff_fresh_agent_filesystem(mut self) -> io::Result<(Self, std::path::PathBuf)> {
        let mut closing = CloseSameActorPhaseOnDrop::new(&self.gate);
        self.gate.require_open()?;
        let (original, parent) = self.original.handoff_fresh_agent_filesystem()?;
        self.original = original;
        self.gate.require_open()?;
        closing.disarm();
        Ok((self, parent))
    }

    pub fn with_original_logind_session(
        mut self, profile_file: &Path, original_login: OwnedFd,
    ) -> io::Result<Self> {
        let mut closing = CloseSameActorPhaseOnDrop::new(&self.gate);
        self.gate.require_open()?;
        self.original = self.original.with_original_logind_session(profile_file, original_login)?;
        self.gate.require_open()?;
        closing.disarm();
        Ok(self)
    }

    pub fn with_registered_notes_from_session(
        mut self, target: &codex_hepta_memory::NotesTargetIdentity, lifetime_ms: u64,
    ) -> io::Result<Self> {
        let mut closing = CloseSameActorPhaseOnDrop::new(&self.gate);
        self.gate.require_open()?;
        self.original = self.original.with_registered_notes_from_session(target, lifetime_ms)?;
        self.gate.require_open()?;
        closing.disarm();
        Ok(self)
    }

    pub fn serve_with_ready(self, ready: impl FnOnce() -> io::Result<()>) -> io::Result<()> {
        worker::serve_original_phase(self, ready)
    }
}

fn phase_root_start() -> io::Result<u64> {
    std::fs::read_to_string("/proc/self/stat")?
        .rsplit_once(") ")
        .and_then(|(_, fields)| fields.split_whitespace().nth(19))
        .and_then(|value| value.parse::<u64>().ok())
        .filter(|value| *value != 0)
        .ok_or_else(|| io::Error::other("actual Root incarnation missing"))
}

//! Shared stop and deadline accounting for the explicit same-actor phase.
//! This gate supplies no writer, lease, outcome, or publication permission.
//! Every effect still enters its original owner and dispatch-witness checks.

use std::collections::BTreeMap;
use std::io;
use std::net::Shutdown;
use std::os::unix::net::UnixStream;
use std::os::unix::net::UnixDatagram;
use std::sync::Arc;
use std::sync::Condvar;
use std::sync::Mutex;
use std::time::Duration;
use std::time::Instant;

use tokio_util::sync::CancellationToken;

const MAX_STREAMS: usize = 16;
const STOP_PROBE: Duration = Duration::from_millis(5);

/// The two time domains remain distinct. Neither field is reconstructed from
/// a later remaining Duration. BOOTTIME also expires across system suspend.
#[derive(Clone, Copy)]
pub(crate) struct SameActorPhaseDeadline {
    instant: Instant,
    boottime_ns: u64,
}

impl SameActorPhaseDeadline {
    /// Only the original Root serving scope calls this, before any service or
    /// ready callback. The same value reaches every original and late lane.
    pub(crate) fn at_original_service_start(lifetime: Duration) -> io::Result<Self> {
        if lifetime.is_zero() || lifetime > Duration::from_secs(300) {
            return Err(refused("original phase lifetime is outside its bound"));
        }
        let boot = crate::root_observation_cache::boottime_ns().map_err(io::Error::other)?;
        let instant = Instant::now()
            .checked_add(lifetime)
            .ok_or_else(|| refused("original phase Instant overflow"))?;
        let boottime_ns = boot
            .checked_add(u64::try_from(lifetime.as_nanos()).map_err(io::Error::other)?)
            .ok_or_else(|| refused("original phase BOOTTIME overflow"))?;
        Ok(Self { instant, boottime_ns })
    }

    /// Data pins captured by the actual receiver and original LiveRoot, plus
    /// the Root-sealed phase bound. A later offer cannot increase either pin.
    pub(crate) fn from_original_receive(
        instant: Instant,
        session_boottime_ns: u64,
        root_phase_boottime_ns: u64,
    ) -> io::Result<Self> {
        if session_boottime_ns == 0 || root_phase_boottime_ns == 0 {
            return Err(refused("original phase deadline is missing"));
        }
        let deadline = Self {
            instant,
            boottime_ns: session_boottime_ns.min(root_phase_boottime_ns),
        };
        deadline.remaining_at(
            crate::root_observation_cache::boottime_ns().map_err(io::Error::other)?,
        )?;
        Ok(deadline)
    }

    pub(crate) fn instant(&self) -> Instant {
        self.instant
    }

    pub(crate) fn boottime_ns(&self) -> u64 {
        self.boottime_ns
    }

    fn remaining_at(&self, now: u64) -> io::Result<Duration> {
        let boot = self.boottime_ns.checked_sub(now)
            .filter(|remaining| *remaining != 0)
            .map(Duration::from_nanos)
            .ok_or_else(|| refused("original phase BOOTTIME end elapsed"))?;
        let local = self.instant.checked_duration_since(Instant::now())
            .filter(|remaining| !remaining.is_zero())
            .ok_or_else(|| refused("original phase Instant end elapsed"))?;
        Ok(boot.min(local))
    }
}

enum OriginalPhaseEndpoint {
    Stream(UnixStream),
    Datagram(UnixDatagram),
}

impl OriginalPhaseEndpoint {
    fn shutdown(&self) {
        match self {
            Self::Stream(stream) => { let _ = stream.shutdown(Shutdown::Both); }
            Self::Datagram(socket) => { let _ = socket.shutdown(Shutdown::Both); }
        }
    }
}

struct GateState {
    closed: bool,
    epoch: u64,
    last_boottime_ns: u64,
    active: usize,
    next_stream: u64,
    streams: BTreeMap<u64, OriginalPhaseEndpoint>,
}

/// The short mutex guards only in-memory admission/accounting. It is never
/// held across an owner callback, filesystem work, a frame, or an await.
pub(crate) struct SameActorPhaseGate {
    deadline: SameActorPhaseDeadline,
    state: Mutex<GateState>,
    changed: Condvar,
    closed: CancellationToken,
}

/// Owns the shutdown alias for exactly one original channel lifetime.
/// Dropping the channel cannot leave an alias keeping its peer alive.
pub(crate) struct SameActorPhaseStream {
    gate: Arc<SameActorPhaseGate>,
    id: u64,
}

/// An original required channel keeps its close responsibility until its
/// actual owner drops. This wraps no authority or alternative transport.
pub(crate) struct RequiredSameActorPhaseChannel {
    closing: CloseSameActorPhaseOnDrop,
    _stream: SameActorPhaseStream,
}

impl RequiredSameActorPhaseChannel {
    pub(crate) fn gate(&self) -> &Arc<SameActorPhaseGate> {
        &self.closing.gate
    }

    pub(crate) fn require_open(&self) -> io::Result<()> {
        self.closing.gate.require_open().map(|_| ())
    }

    pub(crate) fn failure_scope(&self) -> CloseSameActorPhaseOnDrop {
        CloseSameActorPhaseOnDrop::new(&self.closing.gate)
    }
}

pub(crate) struct SameActorPhaseAdmission {
    gate: Arc<SameActorPhaseGate>,
}

/// Cancelling a phase future or losing its response closes all participating
/// lanes. Disarming transfers responsibility; it never reopens a closed gate.
pub(crate) struct CloseSameActorPhaseOnDrop {
    gate: Arc<SameActorPhaseGate>,
    armed: bool,
}

impl SameActorPhaseGate {
    pub(crate) fn from_original_deadline(deadline: SameActorPhaseDeadline) -> io::Result<Arc<Self>> {
        let now = crate::root_observation_cache::boottime_ns().map_err(io::Error::other)?;
        deadline.remaining_at(now)?;
        Ok(Arc::new(Self {
            deadline,
            state: Mutex::new(GateState {
                closed: false,
                epoch: 0,
                last_boottime_ns: now,
                active: 0,
                next_stream: 1,
                streams: BTreeMap::new(),
            }),
            changed: Condvar::new(),
            closed: CancellationToken::new(),
        }))
    }

    pub(crate) fn deadline(&self) -> SameActorPhaseDeadline {
        self.deadline
    }

    fn check_locked(&self, state: &mut GateState) -> io::Result<Duration> {
        if state.closed || self.closed.is_cancelled() {
            return Err(refused("original same-actor phase is closed"));
        }
        // Sample after acquiring the same state guard. A delayed reader cannot
        // mistake a newer concurrent check for physical clock regression.
        let now = crate::root_observation_cache::boottime_ns().map_err(io::Error::other)?;
        if now < state.last_boottime_ns {
            return Err(refused("original phase BOOTTIME regressed"));
        }
        let remaining = self.deadline.remaining_at(now)?;
        state.last_boottime_ns = now;
        Ok(remaining)
    }

    pub(crate) fn require_open(&self) -> io::Result<Duration> {
        let checked = self.state.lock()
            .map_err(|_| refused("original phase gate is poisoned"))
            .and_then(|mut state| self.check_locked(&mut state));
        if checked.is_err() {
            self.close();
        }
        checked
    }

    pub(crate) fn enter_original_lane(self: &Arc<Self>) -> io::Result<SameActorPhaseAdmission> {
        let admitted = (|| {
            let mut state = self.state.lock()
                .map_err(|_| refused("original phase gate is poisoned"))?;
            self.check_locked(&mut state)?;
            state.active = state.active.checked_add(1)
                .ok_or_else(|| refused("original phase active count overflow"))?;
            Ok(SameActorPhaseAdmission { gate: Arc::clone(self) })
        })();
        if admitted.is_err() {
            self.close();
        }
        admitted
    }

    /// Retain a shutdown alias while this exact original channel is owned.
    /// The returned guard must be kept inside that channel, never detached.
    pub(crate) fn retain_original_stream(
        self: &Arc<Self>,
        stream: &UnixStream,
    ) -> io::Result<SameActorPhaseStream> {
        let retained = (|| {
            let alias = OriginalPhaseEndpoint::Stream(stream.try_clone()?);
            let mut state = self.state.lock()
                .map_err(|_| refused("original phase gate is poisoned"))?;
            self.check_locked(&mut state)?;
            if state.streams.len() >= MAX_STREAMS {
                return Err(refused("original phase stream bound exceeded"));
            }
            let id = state.next_stream;
            state.next_stream = id.checked_add(1)
                .ok_or_else(|| refused("original phase stream identity exhausted"))?;
            state.streams.insert(id, alias);
            Ok(SameActorPhaseStream { gate: Arc::clone(self), id })
        })();
        if retained.is_err() {
            self.close();
        }
        retained
    }

    pub(crate) fn retain_required_original_stream(
        self: &Arc<Self>,
        stream: &UnixStream,
    ) -> io::Result<RequiredSameActorPhaseChannel> {
        let closing = CloseSameActorPhaseOnDrop::new(self);
        let stream = self.retain_original_stream(stream)?;
        self.require_open()?;
        Ok(RequiredSameActorPhaseChannel { closing, _stream: stream })
    }

    pub(crate) fn retain_original_datagram(
        self: &Arc<Self>,
        stream: &UnixDatagram,
    ) -> io::Result<SameActorPhaseStream> {
        let retained = (|| {
            let alias = OriginalPhaseEndpoint::Datagram(stream.try_clone()?);
            let mut state = self.state.lock()
                .map_err(|_| refused("original phase gate is poisoned"))?;
            self.check_locked(&mut state)?;
            if state.streams.len() >= MAX_STREAMS {
                return Err(refused("original phase stream bound exceeded"));
            }
            let id = state.next_stream;
            state.next_stream = id.checked_add(1)
                .ok_or_else(|| refused("original phase stream identity exhausted"))?;
            state.streams.insert(id, alias);
            Ok(SameActorPhaseStream { gate: Arc::clone(self), id })
        })();
        if retained.is_err() {
            self.close();
        }
        retained
    }

    pub(crate) fn close(&self) {
        self.closed.cancel();
        // A poisoned guard cannot authorize anything. Its retained socket
        // aliases are still owned here and must be shut down to wake waiters.
        let streams = {
            let mut state = match self.state.lock() {
                Ok(state) => state,
                Err(poisoned) => poisoned.into_inner(),
            };
            state.closed = true;
            state.epoch = state.epoch.saturating_add(1);
            std::mem::take(&mut state.streams)
        };
        self.changed.notify_all();
        for stream in streams.into_values() {
            stream.shutdown();
        }
    }

    pub(crate) async fn cancelled(&self) {
        self.closed.cancelled().await;
    }

    /// Run in the original scoped Root thread or required daemon worker.
    /// This is not detached and never refreshes an authority observation.
    /// A short stop probe also notices BOOTTIME advancing across suspend.
    pub(crate) fn watch_original_deadline(&self) {
        loop {
            let mut state = match self.state.lock() {
                Ok(state) => state,
                Err(poisoned) => { drop(poisoned); self.close(); return; }
            };
            if state.closed || self.closed.is_cancelled() {
                return;
            }
            let remaining = match self.check_locked(&mut state) {
                Ok(remaining) => remaining,
                Err(_) => { drop(state); self.close(); return; }
            };
            match self.changed.wait_timeout(state, remaining.min(STOP_PROBE)) {
                Ok((next, _)) => drop(next),
                Err(poisoned) => { drop(poisoned); self.close(); return; }
            }
        }
    }

    pub(crate) fn notify_original_waiters(&self) {
        match self.state.lock() {
            Ok(mut state) => {
                if let Some(next) = state.epoch.checked_add(1) {
                    state.epoch = next;
                } else {
                    drop(state);
                    self.close();
                    return;
                }
            }
            Err(poisoned) => {
                drop(poisoned);
                self.close();
                return;
            }
        }
        self.changed.notify_all();
    }

    /// Snapshot before checking an acknowledgement. A sender publishes its
    /// response before notifying; comparing this epoch prevents a lost wakeup.
    pub(crate) fn original_wait_epoch(&self) -> io::Result<u64> {
        let result = (|| {
            let mut state = self.state.lock()
                .map_err(|_| refused("original phase gate is poisoned"))?;
            self.check_locked(&mut state)?;
            Ok(state.epoch)
        })();
        if result.is_err() { self.close(); }
        result
    }

    pub(crate) fn wait_original_change(&self, epoch: u64) -> io::Result<()> {
        let result = (|| {
            let mut state = self.state.lock()
                .map_err(|_| refused("original phase gate is poisoned"))?;
            let remaining = self.check_locked(&mut state)?;
            if state.epoch == epoch {
                // This is only a wait budget; the two retained absolute ends
                // are checked again after wakeup and are never recomputed.
                state = self.changed.wait_timeout(state, remaining.min(STOP_PROBE))
                    .map_err(|_| refused("original phase wait is poisoned"))?.0;
            }
            self.check_locked(&mut state)?;
            Ok(())
        })();
        if result.is_err() { self.close(); }
        result
    }
}

impl Drop for SameActorPhaseStream {
    fn drop(&mut self) {
        let stream = match self.gate.state.lock() {
            Ok(mut state) => state.streams.remove(&self.id),
            Err(poisoned) => {
                drop(poisoned);
                self.gate.close();
                return;
            }
        };
        // Removing the alias ends only this registration. The original
        // channel owner performs its own close; gate.close() still shuts down
        // every alias retained at the instant of shared failure.
        drop(stream);
    }
}

impl Drop for SameActorPhaseAdmission {
    fn drop(&mut self) {
        let valid = match self.gate.state.lock() {
            Ok(mut state) => match state.active.checked_sub(1) {
                Some(active) => { state.active = active; true }
                None => false,
            },
            Err(_) => false,
        };
        if valid {
            self.gate.notify_original_waiters();
        } else {
            self.gate.close();
        }
    }
}

impl CloseSameActorPhaseOnDrop {
    pub(crate) fn new(gate: &Arc<SameActorPhaseGate>) -> Self {
        Self { gate: Arc::clone(gate), armed: true }
    }

    pub(crate) fn disarm(&mut self) {
        self.armed = false;
    }
}

impl Drop for CloseSameActorPhaseOnDrop {
    fn drop(&mut self) {
        if self.armed {
            self.gate.close();
        }
    }
}

fn refused(message: &'static str) -> io::Error {
    io::Error::other(message)
}
